export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4;
  const g = inputs.gravity ?? 9.8;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const tEnd = (2 * u) / g;

  const currentT = Math.min(Math.max(time, 0), tEnd);

  const yToss = u * currentT - 0.5 * g * currentT * currentT;
  const vToss = u - g * currentT;
  const aToss = -g;

  let yDrop = yTop;
  let vDrop = 0;
  let aDrop = 0;

  if (currentT >= tTop) {
    const dt = currentT - tTop;
    yDrop = yTop - 0.5 * g * dt * dt;
    vDrop = -g * dt;
    aDrop = -g;
  }

  const laneW = 280;
  const laneH = 340;
  const laneY = 40;
  const xToss = 20;
  const xDrop = 340;

  let stateToss = "At launch";
  if (Math.abs(currentT - tTop) < 0.01) {
    stateToss = "At the top";
  } else if (currentT > tTop) {
    stateToss = currentT >= tEnd - 0.01 ? "At launch height" : "Falling";
  } else if (currentT > 0) {
    stateToss = "Rising";
  }

  let stateDrop = "Held in place";
  if (currentT >= tTop) {
    if (Math.abs(currentT - tTop) < 0.01) {
      stateDrop = "Just released";
    } else if (currentT >= tEnd - 0.01) {
      stateDrop = "At launch height";
    } else {
      stateDrop = "Falling together";
    }
  }

  const tossPanel = sdk.panel({
    id: "lane.toss",
    x: xToss,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Toss Lane",
    state: stateToss
  });

  const dropPanel = sdk.panel({
    id: "lane.drop",
    x: xDrop,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Drop Lane",
    state: stateDrop
  });

  const pxPerM = 110;
  const yGround = laneY + laneH - 50;
  const cxToss = xToss + 140;
  const cxDrop = xDrop + 140;

  const ballYToss = yGround - yToss * pxPerM;
  const ballYDrop = yGround - yDrop * pxPerM;
  const topYPx = yGround - yTop * pxPerM;

  const axisToss = sdk.axis("axis.toss", {
    x: xToss + 40,
    y: yGround,
    length: 240,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const axisDrop = sdk.axis("axis.drop", {
    x: xDrop + 40,
    y: yGround,
    length: 240,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const ballToss = sdk.circle("ball.toss", cxToss, ballYToss, 28);
  const ballDrop = sdk.circle("ball.drop", cxDrop, ballYDrop, 28);

  const gate = sdk.gate("gate", cxDrop, topYPx, {
    open: currentT >= tTop,
    w: 36,
    label: "Release Gate"
  });

  const vScale = 15;
  const aScale = 6;

  const vecVToss = sdk.vector("vec.v.toss", { x: cxToss - 18, y: ballYToss }, {
    value: vToss,
    direction: "up",
    scale: vScale,
    label: "v"
  });

  const vecAToss = sdk.vector("vec.a.toss", { x: cxToss + 18, y: ballYToss }, {
    value: aToss,
    direction: "up",
    scale: aScale,
    label: "a"
  });

  const vecVDrop = sdk.vector("vec.v.drop", { x: cxDrop - 18, y: ballYDrop }, {
    value: vDrop,
    direction: "up",
    scale: vScale,
    label: "v"
  });

  const vecADrop = sdk.vector("vec.a.drop", { x: cxDrop + 18, y: ballYDrop }, {
    value: aDrop,
    direction: "up",
    scale: aScale,
    label: "a"
  });

  const calloutToss = sdk.callout(cxToss + 35, ballYToss - 20, [
    `v = ${sdk.format(vToss, 2)} m/s`,
    `a = ${sdk.format(aToss, 2)} m/s²`
  ], { id: "callout.toss" });

  const calloutDrop = sdk.callout(cxDrop + 35, ballYDrop - 20, [
    `v = ${sdk.format(vDrop, 2)} m/s`,
    `a = ${sdk.format(aDrop, 2)} m/s²`
  ], { id: "callout.drop" });

  const objects = [
    ...tossPanel,
    ...dropPanel,
    axisToss,
    axisDrop,
    ...gate,
    ballToss,
    ballDrop,
    ...vecVToss,
    ...vecAToss,
    ...vecVDrop,
    ...vecADrop,
    ...calloutToss,
    ...calloutDrop
  ];

  if (currentT >= tTop) {
    objects.push(
      sdk.circle("outline.toss", cxToss, topYPx, 28, { opacity: 0.35, role: "neutral" }),
      sdk.circle("outline.drop", cxDrop, topYPx, 28, { opacity: 0.35, role: "neutral" })
    );
  }

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tTop,
      apexHeight: yTop,
      tossedVelocity: vToss,
      tossedAcceleration: aToss,
      tossedHeight: yToss,
      dropVelocity: vDrop,
      dropAcceleration: aDrop,
      dropHeight: yDrop
    }
  };
}
